function shuffledOptions(answer: string, distractors: string[]) {
  return [answer, ...distractors.filter((item) => item !== answer)].slice(0, 4);
}
function sectionQuestions(unit: A2Unit, section: "grammar" | "vocabulary" | "listening" | "reading") {
  if (section === "grammar") return unit.grammarQuestions.map((item) => ({ ...item, options: shuffledOptions(item.answer, item.distractors) }));
  if (section === "vocabulary") return unit.vocabularyQuestions.map((item) => ({ ...item, options: shuffledOptions(item.answer, item.distractors) }));
  if (section === "listening") return unit.listeningQuestions.map((item) => ({ ...item, options: shuffledOptions(item.answer, item.distractors) }));
  return unit.readingQuestions.map((item) => ({ ...item, options: shuffledOptions(item.answer, item.distractors) }));
}

export function buildA2UnitSections(unit: A2Unit) {
  return {
    objective: unit.objective,
    sections: [
      { type: "grammar", title: "Gramática · " + unit.title, body: unit.grammar + "\n\n" + unit.objective, example: unit.grammarQuestions.map((item) => item.prompt + " → " + item.answer).join("\n"), exampleTranslation: "Estudia la regla, completa cada ejercicio y lee la explicación después de responder." },
      { type: "vocabulary", title: "Vocabulario · " + unit.title, body: unit.vocabulary, example: unit.vocabularyQuestions.map((item) => item.prompt + " → " + item.answer).join("\n"), exampleTranslation: "Intenta explicar cada palabra en inglés y úsala en una frase propia." },
      { type: "listening", title: "Listening · " + unit.title, body: "Escucha la lectura en inglés británico. Primero identifica el tema general; después escucha buscando nombres, acciones y detalles.", audioText: unit.passage, transcript: unit.passage, transcriptTranslation: "Lee la transcripción después de intentar comprender el audio." },
      { type: "reading", title: "Reading · " + unit.title, body: "Lee el texto primero para captar la idea general y después para localizar detalles concretos.", example: unit.passage, exampleTranslation: "Localiza en el texto la frase que justifica cada respuesta." },
    ],
  };
}

function expandForPractice(unit: A2Unit, section: "grammar" | "vocabulary" | "listening" | "reading") {
  const original = sectionQuestions(unit, section);
  const contextual = original.map((item, index) => ({
    ...item,
    prompt: section === "grammar"
      ? `Aplica la regla «${unit.grammar}» (ejercicio ${index + 6}): ${item.prompt}`
      : section === "vocabulary"
        ? `En el contexto de «${unit.title}», ${item.prompt}`
        : section === "listening"
          ? `Vuelve a escuchar la unidad «${unit.title}». ${item.prompt}`
          : `Vuelve a la lectura de «${unit.title}» y localiza la evidencia. ${item.prompt}`
  }));
  const transfer = original.map((item, index) => ({
    ...item,
    prompt: section === "grammar"
      ? `Elige la forma correcta para una situación real de esta unidad: ${unit.objective} ${item.prompt}`
      : section === "vocabulary"
        ? `Comprueba el significado y uso de la palabra clave. ${item.prompt}`
        : section === "listening"
          ? `Detalle del diálogo (pregunta ${index + 11}): ${item.prompt}`
          : `Comprensión detallada del texto (pregunta ${index + 11}): ${item.prompt}`
  }));
  return [...original, ...contextual, ...transfer].map((item, index) => ({
    ...item,
    id: `a2-${String(unit.n).padStart(2,"0")}-${section}-${String(index + 1).padStart(2,"0")}`,
    number: index + 1,
    explanation: section === "grammar"
      ? `Regla: ${unit.grammar} Respuesta correcta: ${item.answer}.`
      : section === "vocabulary"
        ? `Vocabulario de esta unidad: ${unit.vocabulary} Respuesta: ${item.answer}.`
        : section === "listening"
          ? `Escucha y localiza la información en la transcripción: ${unit.passage}`
          : `Vuelve al texto y localiza la frase que confirma la respuesta: ${unit.passage}`
  }));
}

export const a2QuestionSets = Object.fromEntries(a2Units.map((unit) => [unit.n, {
  grammar: expandForPractice(unit, "grammar"),
  vocabulary: expandForPractice(unit, "vocabulary"),
  listening: expandForPractice(unit, "listening"),
  reading: expandForPractice(unit, "reading"),
}])) as Record<number, Record<"grammar" | "vocabulary" | "listening" | "reading", { id: string; number: number; prompt: string; answer: string; distractors: string[]; options: string[]; explanation: string }[]>>;
